import { useNavigate } from 'react-router-dom';
import { LEVELS } from '@lexpad/core';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { useCurrentDay } from '@/lib/useCurrentDay.js';
import { loadToday, type TodayData } from '@/features/today/data.js';
import styles from './Decks.module.css';

const EMPTY = { topics: [], levels: [], kinds: [], counts: { total: 0 } } as unknown as TodayData;

/**
 * Decks: the whole notebook cut by level and by topic. The prototype keeps
 * these off Today and behind its "By topic or level" row, so Today stays a
 * single decision and this screen carries the browsing.
 */
export function Decks(): React.JSX.Element {
  const navigate = useNavigate();
  const now = useCurrentDay();
  const data = useLiveQuery(() => loadToday(now), EMPTY, [now]);
  const biggest = Math.max(...data.topics.map((topic) => topic.count), 1);

  const byLevel = new Map(data.levels.map((entry) => [entry.level, entry.count]));

  return (
    <main className={styles.screen}>
      <header className={styles.head}>
        <button
          type="button"
          className={styles.back}
          aria-label={t('action.back')}
          onClick={() => {
            void navigate('/');
          }}
        >
          <Icon name="chevronLeft" size={20} weight={2} />
        </button>
        <h1 className={styles.title}>{t('decks.title')}</h1>
      </header>

      <section className={styles.section}>
        <h2 className={styles.sectionTitle}>{t('decks.byLevel')}</h2>
        <div className={styles.levels}>
          {LEVELS.map((level) => {
            const count = byLevel.get(level) ?? 0;
            return (
              <button
                key={level}
                type="button"
                className={styles.level}
                disabled={count === 0}
                onClick={() => {
                  void navigate(`/session?deck=level&level=${level}`);
                }}
              >
                <span className={styles.levelName}>{level}</span>
                <span className={styles.levelCount}>{count}</span>
              </button>
            );
          })}
        </div>
      </section>

      {data.kinds.length > 0 && (
        <section className={styles.section}>
          <h2 className={styles.sectionTitle}>{t('decks.byKind')}</h2>
          <div className={styles.kinds}>
            {data.kinds.map((entry) => (
              <button
                key={entry.kind}
                type="button"
                className={styles.level}
                onClick={() => {
                  void navigate(`/session?deck=kind&kind=${entry.kind}`);
                }}
              >
                <span className={styles.kindName}>{t(`kind.${entry.kind}`)}</span>
                <span className={styles.levelCount}>{entry.count}</span>
              </button>
            ))}
          </div>
        </section>
      )}

      <section className={styles.section}>
        <h2 className={styles.sectionTitle}>{t('decks.byTopic')}</h2>
        {data.topics.length === 0 ? (
          <EmptyState
            compact
            icon="grid"
            tone="quiet"
            title={t('decks.noTopicsTitle')}
            body={t('decks.noTopics')}
          />
        ) : (
          <div className={styles.topics}>
            {data.topics.map((topic) => (
              <button
                key={topic.name}
                type="button"
                className={styles.topic}
                onClick={() => {
                  void navigate(`/session?deck=topic&topic=${encodeURIComponent(topic.name)}`);
                }}
              >
                <span className={styles.topicName}>{topic.name.replace(/-/g, ' ')}</span>
                <span className={styles.topicMeta}>
                  <span className={styles.topicCount}>{topic.count}</span>
                  <span className={styles.track}>
                    <span
                      className={styles.fill}
                      style={{ width: `${String(Math.round((topic.count / biggest) * 100))}%` }}
                    />
                  </span>
                </span>
              </button>
            ))}
          </div>
        )}
      </section>
    </main>
  );
}
